sp_widget.client_script:
api.controller = function() {

    var c = this;

    console.log("======================================");
    console.log("     FOOD BASE PROBLEM DASHBOARD");
    console.log("======================================");


    // ==========================================
    // DASHBOARD COUNTS
    // ==========================================

    console.log("Total Requests:",
        c.data.totalRequests);

    console.log("Pending:",
        c.data.pending);

    console.log("In Progress:",
        c.data.inProgress);

    console.log("Closed:",
        c.data.closed);


    // ==========================================
    // RECENT REQUESTS
    // ==========================================

    console.log("======================================");
    console.log("Recent Requests:");
    console.log("======================================");

    console.log(
        "Number of Recent Requests:",
        c.data.recentRequests.length
    );

    console.log(
        c.data.recentRequests
    );


    // ==========================================
    // PRINT EACH RECENT REQUEST
    // ==========================================

    for (var i = 0;
         i < c.data.recentRequests.length;
         i++) {

        var request =
            c.data.recentRequests[i];

        console.log(
            "Request " + (i + 1) + ":",
            request
        );

    }


    // ==========================================
    // COMPLETE SERVER DATA
    // ==========================================

    console.log("======================================");
    console.log("Complete Server Data:");
    console.log("======================================");

    console.log(c.data);

};

sp_widget.css:
.staff-dashboard {
    display: flex;
    min-height: 100vh;
    background: #f5f7fa;
}


/* =========================
   SIDEBAR
   ========================= */

.sidebar {
    width: 240px;
    min-height: 100vh;
    background: #ffffff;
    border-right: 1px solid #e5e7eb;

    display: flex;
    flex-direction: column;
    justify-content: space-between;

    flex-shrink: 0;
}


/* =========================
   SIDEBAR MENU
   ========================= */

.sidebar-menu {
    padding: 25px 15px;
}


.menu-item {
    padding: 13px 15px;
    margin-bottom: 8px;

    border-radius: 6px;

    color: #374151;
    background: transparent;

    font-size: 15px;
    font-weight: 500;

    cursor: pointer;

    transition: background 0.2s ease,
                color 0.2s ease;
}


.menu-item:hover {
    background: #f3f4f6;
    color: #111827;
}


.menu-item.active {
    background: #eef2ff;
    color: #4f46e5;

    font-weight: 600;
}


/* =========================
   SIDEBAR USER
   ========================= */

.sidebar-user {
    padding: 18px;

    border-top: 1px solid #e5e7eb;

    display: flex;
    align-items: center;

    gap: 10px;
}


.sidebar-user-icon {
    width: 38px;
    height: 38px;

    border-radius: 50%;

    background: #eef2ff;

    display: flex;
    align-items: center;
    justify-content: center;

    font-size: 18px;
}


.sidebar-user-info {
    display: flex;
    flex-direction: column;
}


.sidebar-user-name {
    font-size: 14px;
    font-weight: 600;

    color: #1f2937;
}


.sidebar-user-role {
    margin-top: 3px;

    font-size: 12px;

    color: #6b7280;
}

sp_widget.script:
(function() {

    // ==========================================
    // DASHBOARD DATA
    // ==========================================

    data.totalRequests = 0;
    data.pending = 0;
    data.inProgress = 0;
    data.closed = 0;

    data.recentRequests = [];


    // ==========================================
    // GROUP SYS IDS
    // ==========================================

    var hostelAdminGroup =
        '1754d95bdd1f03107f44143a6accf85b';

    var hostelManagementGroup =
        '9374d15fdd1f03107f44143a6accf88d';


    // ==========================================
    // GET FOOD BASE PROBLEM RECORDS
    // ==========================================

    var problemGR = new GlideRecord(
        'x_snc_campus_foo_1_food_base_problem'
    );


    // ==========================================
    // ADMIN GROUP OR MANAGEMENT GROUP
    // ==========================================

    problemGR.addQuery(
        'assignment_group',
        'IN',
        hostelAdminGroup + ',' + hostelManagementGroup
    );

    problemGR.query();


    // ==========================================
    // COUNT DASHBOARD RECORDS
    // ==========================================

    while (problemGR.next()) {

        // Total Requests
        data.totalRequests++;


        // Get status
        var status =
            problemGR.getDisplayValue('status');


        // ==========================================
        // PENDING
        // Active records
        // ==========================================

        if (status == 'Active') {

            data.pending++;

        }


        // ==========================================
        // IN PROGRESS
        // Hostel Management Group
        // ==========================================

        if (
            problemGR.getValue('assignment_group') ==
            hostelManagementGroup
        ) {

            data.inProgress++;

        }


        // ==========================================
        // CLOSED
        // Non-active records
        // ==========================================

        if (status != 'Active') {

            data.closed++;

        }

    }


    // ==========================================
    // RECENT REQUESTS
    // HOSTEL ADMIN GROUP + ACTIVE
    // ==========================================

    var recentGR = new GlideRecord(
        'x_snc_campus_foo_1_food_base_problem'
    );


    recentGR.addQuery(
        'assignment_group',
        hostelAdminGroup
    );

    recentGR.addQuery(
        'status',
        'Active'
    );

    recentGR.orderByDesc('sys_created_on');

    recentGR.setLimit(5);

    recentGR.query();


    // ==========================================
    // GET FIRST 5 RECENT REQUESTS
    // ==========================================

    while (recentGR.next()) {

        var request = {};

        request.sys_id =
            recentGR.getUniqueValue();

        request.number =
            recentGR.getDisplayValue('number');

        request.problem_type =
            recentGR.getDisplayValue('problem_type');

        request.mess_hall =
            recentGR.getDisplayValue('mess_hall');

        request.meal_type =
            recentGR.getDisplayValue('meal_type');

        // HTML already expects "state"
        // Food Base Problem actual field is "status"
        request.state =
            recentGR.getDisplayValue('status');

        request.description =
            recentGR.getDisplayValue('description');

        request.priority =
            recentGR.getDisplayValue('current_priority');


        data.recentRequests.push(request);

    }

})();
